// The vendors example's transpile output: developer-owned generated source and
// the tests that drive it. This example exercises the read side of
// authorization (Reference §22, "The actor"): record-level and field-level
// `visible to` clauses, `visible to anyone`, the spec-wide default, the read
// surface for a viewer, and a refusal projected for the actor. Regenerated by
// `gradle generate`.
plugins {
    kotlin("jvm")
}

group = "velle"

repositories {
    mavenCentral()
}

dependencies {
    implementation(project(":compiler"))
    testImplementation(kotlin("test"))
    testImplementation(project(":stores:sqlite"))
}

tasks.test {
    useJUnitPlatform()
}

tasks.register<JavaExec>("generate") {
    description = "Regenerate the Vendors typed surface and executable specs from vendors.velle"
    classpath = sourceSets["main"].runtimeClasspath
    mainClass.set("velle.GenerateKt")
    args("../vendors.velle", "Vendors")
}

kotlin {
    compilerOptions {
        jvmTarget.set(org.jetbrains.kotlin.gradle.dsl.JvmTarget.JVM_21)
    }
}

java {
    sourceCompatibility = JavaVersion.VERSION_21
    targetCompatibility = JavaVersion.VERSION_21
}
